import java.io.*;
import java.util.*;

public class Main {
    static boolean ws(char c) { return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == 11 || c == '\f'; }

    record Event(long ts, String receiver, String subject) {}

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in), 1 << 16);
        int n = Integer.parseInt(br.readLine().trim());
        TreeMap<String, List<Event>> groups = new TreeMap<>();
        for (int i = 0; i < n; i++) {
            String line = br.readLine();
            if (line == null) break;
            // Three whitespace-separated fields, then the subject is the rest of the line.
            int p = 0;
            String[] f = new String[3];
            for (int t = 0; t < 3; t++) {
                while (p < line.length() && ws(line.charAt(p))) p++;
                int q = p;
                while (q < line.length() && !ws(line.charAt(q))) q++;
                f[t] = line.substring(p, q);
                p = q;
            }
            while (p < line.length() && ws(line.charAt(p))) p++;
            groups.computeIfAbsent(f[1], k -> new ArrayList<>()).add(new Event(Long.parseLong(f[0]), f[2], line.substring(p)));
        }
        Comparator<Event> order = Comparator.comparingLong(Event::ts)
                .thenComparing(Event::receiver).thenComparing(Event::subject);
        List<String> out = new ArrayList<>();
        for (Map.Entry<String, List<Event>> g : groups.entrySet()) {
            out.add("sender: " + g.getKey());
            List<Event> items = g.getValue();
            items.sort(order);
            for (Event e : items)
                out.add(e.ts() + " " + e.receiver() + (e.subject().isEmpty() ? "" : " " + e.subject()));
        }
        StringBuilder sb = new StringBuilder();
        sb.append(out.size()).append('\n');
        for (String s : out) sb.append(s).append('\n');
        System.out.print(sb);
    }
}

package main

import (
	"bufio"
	"os"
	"sort"
	"strconv"
	"strings"
)

type event struct {
	ts                int64
	receiver, subject string
}

func ws(c byte) bool { return c == ' ' || c == '\t' || c == '\r' || c == '\n' || c == '\v' || c == '\f' }

func main() {
	sc := bufio.NewScanner(os.Stdin)
	sc.Buffer(make([]byte, 1<<20), 1<<20)
	sc.Scan()
	n, _ := strconv.Atoi(strings.TrimSpace(sc.Text()))
	groups := map[string][]event{}
	for i := 0; i < n && sc.Scan(); i++ {
		line := sc.Text()
		// Three whitespace-separated fields, then the subject is the rest of the line.
		p := 0
		var f [3]string
		for t := 0; t < 3; t++ {
			for p < len(line) && ws(line[p]) {
				p++
			}
			q := p
			for q < len(line) && !ws(line[q]) {
				q++
			}
			f[t] = line[p:q]
			p = q
		}
		for p < len(line) && ws(line[p]) {
			p++
		}
		ts, _ := strconv.ParseInt(f[0], 10, 64)
		groups[f[1]] = append(groups[f[1]], event{ts, f[2], line[p:]})
	}
	senders := make([]string, 0, len(groups))
	for s := range groups {
		senders = append(senders, s)
	}
	sort.Strings(senders)
	var out []string
	for _, s := range senders {
		out = append(out, "sender: "+s)
		items := groups[s]
		sort.Slice(items, func(i, j int) bool {
			a, b := items[i], items[j]
			if a.ts != b.ts {
				return a.ts < b.ts
			}
			if a.receiver != b.receiver {
				return a.receiver < b.receiver
			}
			return a.subject < b.subject
		})
		for _, e := range items {
			line := strconv.FormatInt(e.ts, 10) + " " + e.receiver
			if e.subject != "" {
				line += " " + e.subject
			}
			out = append(out, line)
		}
	}
	w := bufio.NewWriter(os.Stdout)
	defer w.Flush()
	w.WriteString(strconv.Itoa(len(out)) + "\n")
	for _, s := range out {
		w.WriteString(s + "\n")
	}
}
